Method.Source:
public static void main(Args _args)
{
    AVAProdStatisticsController controller = new AVAProdStatisticsController();

    ReportName reportName = ssrsReportStr(AVAProdStatisticsReport, Report);
    controller.parmShowDialog(true);

    controller.parmReportName(reportName);
    controller.parmDialogCaption("@NDX:NXAProdStatistics");
    controller.parmArgs(_args);
    controller.startOperation();
}
